from pathlib import Path
p = Path('client/app/src/main/java/me/rerere/rikkahub/feature/material/MaterialEditTools.kt')
s = p.read_text(encoding='utf-8')
s = s.replace('setOf("offset", "count", "sheet")', 'setOf("offset", "count", "sheet", "slide", "runs")')
s = s.replace('"docx" -> MaterialEditor.wordParagraphs(file, offset, count);', '"docx" -> if (selection["runs"]?.jsonPrimitive?.boolean == true) MaterialEditor.textRuns(file, "docx", 0, offset, count) else MaterialEditor.wordParagraphs(file, offset, count); "pptx" -> MaterialEditor.textRuns(file, "pptx", selection.getValue("slide").jsonPrimitive.int, offset, count);')
s = s.replace('首批结构编辑仅支持docx/xlsx', '结构编辑支持docx/xlsx/pptx')
s = s.replace('首批Excel编辑仅支持无公式工作簿，Word仅简单同字符样式文本段落。', 'Word复杂段落可用runs:true检查单个文本运行；PPT指定slide物理页检查文本运行。Excel可编辑含公式工作簿的常量，公式保留并清除旧缓存，需Office打开重算。')
s = s.replace('operation=replace_paragraph或set_cells或pdf_select_pages', 'operation=replace_paragraph或replace_text_run或set_cells或pdf_select_pages')
s = s.replace('仅简单同字符样式段落；Excel', '仅简单同字符样式段落；replace_text_run为Word/PPT单个文本运行{index:1,expectedText:原文,text:新文}，PPT另需slide:1；保留相邻样式/图片/公式，较长文字可能溢出，需打开核对；Excel')
s = s.replace('不支持含公式/宏/签名工作簿', '可改含公式工作簿常量，保留公式并删除旧计算缓存，需Office打开重新计算，禁止修改公式单元格、宏及签名')
s = s.replace('setOf("replace_paragraph", "set_cells", "pdf_select_pages")', 'setOf("replace_paragraph", "replace_text_run", "set_cells", "pdf_select_pages")')
s = s.replace('require(operation != "set_cells" || source.extension == "xlsx")', 'require(operation != "set_cells" || source.extension == "xlsx")\n            require(operation != "replace_text_run" || source.extension in setOf("docx", "pptx"))')
s = s.replace('"edit-v1:', '"edit-v2:')
s = s.replace('when (operation) { "replace_paragraph"', 'when (operation) { "replace_text_run" -> MaterialEditor.replaceTextRun(file, output, source.extension, spec); "replace_paragraph"')
s = s.replace('"操作$operation 已完成；原文件保留，限所声明的编辑范围"', '"操作$operation 已完成；原文件保留；Excel公式需Office打开重算，PPT/Word需核对文字溢出与排版。"')
p.write_text(s, encoding='utf-8')
